/**
 * Rapids Row sounds: WAV files generated by scripts/gen-rapids-audio.mjs (Gemini writes a synth recipe
 * per sound, the script renders it). WebAudio playback; a missing or broken file is just silent.
 *
 *   const audio = createAudio('assets/audio/');
 *   audio.play('splash_2', { volume, rate, pan });   audio.play('splash') picks splash_1..3
 *   const h = audio.loop('river_loop', { volume });   h.setVolume(v); h.setRate(r); h.stop();
 *   audio.setMusic(true);  audio.setMaster(0.8);  audio.unlock();   // unlock on a user gesture
 */
const NAMES = ['splash_1', 'splash_2', 'splash_3', 'rock_hit', 'log_hit', 'bank_scrape', 'coin', 'checkpoint', 'beep', 'go', 'finish', 'cheer', 'moo', 'river_loop', 'rapids_loop', 'music_loop', 'click'];
const MUSIC_VOLUME = 0.22;

export function createAudio(baseUrl = 'assets/audio/') {
  const AC = window.AudioContext || window.webkitAudioContext;
  const ctx = AC ? new AC() : null;
  const master = ctx?.createGain();
  if (master) master.connect(ctx.destination);
  /** name → AudioBuffer (only the ones that loaded) */
  const buffers = new Map();
  /** Loops asked for before their buffer arrived start once it does. */
  const waiting = new Map();

  async function load(name, file = `${name}.wav`) {
    try {
      const r = await fetch(baseUrl + file);
      if (!r.ok) return;
      const buf = await ctx.decodeAudioData(await r.arrayBuffer());
      buffers.set(name, buf);
      for (const start of waiting.get(name) || []) start();
      waiting.delete(name);
    } catch {
      /* missing or undecodable: stays silent */
    }
  }

  const ready = !ctx
    ? Promise.resolve()
    : fetch(baseUrl + 'manifest.json')
        .then((r) => (r.ok ? r.json() : null))
        .catch(() => null)
        .then((m) => {
          // The manifest is {files: {name: {...}}} (an array or {sounds:[...]} also works); plus the fixed list.
          const list = Array.isArray(m) ? m : Array.isArray(m?.sounds) ? m.sounds : m?.files && typeof m.files === 'object' ? Object.keys(m.files) : [];
          const names = new Set(NAMES);
          for (const e of list) if (typeof e === 'string') names.add(e.replace(/\.wav$/, ''));
          else if (e?.name) names.add(e.name);
          return Promise.all([...names].map((n) => load(n)));
        });

  /** 'splash' → one of splash_1..3 when there's no plain 'splash'. */
  function resolve(name) {
    if (buffers.has(name)) return name;
    const variants = [...buffers.keys()].filter((k) => k.startsWith(name + '_') && /_\d+$/.test(k));
    return variants.length ? variants[(Math.random() * variants.length) | 0] : null;
  }

  function voice(buf, { volume = 1, rate = 1, pan = 0, loop = false } = {}) {
    const src = ctx.createBufferSource();
    src.buffer = buf;
    src.loop = loop;
    src.playbackRate.value = rate;
    const gain = ctx.createGain();
    gain.gain.value = volume;
    let out = gain;
    if (pan && ctx.createStereoPanner) {
      const p = ctx.createStereoPanner();
      p.pan.value = Math.max(-1, Math.min(1, pan));
      gain.connect(p);
      out = p;
    }
    src.connect(gain);
    out.connect(master);
    src.start();
    return { src, gain };
  }

  function play(name, opts = {}) {
    if (!ctx || ctx.state !== 'running') return;
    const n = resolve(name);
    if (n) voice(buffers.get(n), opts);
  }

  function loop(name, { volume = 1 } = {}) {
    let v = null, vol = volume, rate = 1, stopped = false;
    const start = () => {
      if (stopped || v || !ctx) return;
      v = voice(buffers.get(name), { volume: vol, rate, loop: true });
    };
    if (buffers.has(name)) start();
    else if (ctx) waiting.set(name, [...(waiting.get(name) || []), start]);
    const ramp = (param, to) => param.setTargetAtTime(to, ctx.currentTime, 0.15);
    return {
      setVolume(x) {
        vol = x;
        if (v) ramp(v.gain.gain, x);
      },
      setRate(r) {
        rate = r;
        if (v) ramp(v.src.playbackRate, r);
      },
      stop() {
        stopped = true;
        if (!v) return;
        ramp(v.gain.gain, 0);
        const s = v.src;
        setTimeout(() => s.stop(), 600);
        v = null;
      },
    };
  }

  let music = null;
  return {
    ready,
    unlock() {
      if (ctx && ctx.state !== 'running') ctx.resume().catch(() => {});
    },
    play,
    loop,
    setMusic(on) {
      if (on && !music) music = loop('music_loop', { volume: MUSIC_VOLUME });
      else if (!on && music) {
        music.stop();
        music = null;
      }
    },
    setMaster(v) {
      if (master) master.gain.value = v;
    },
  };
}
